def minSwapsAlternating(s):
    n = len(s)
    ones = s.count('1')
    zeros = n - ones
    if abs(ones - zeros) > 1:
        return -1
    best = None
    for first in (0, 1):
        # target character at index i is (first + i) % 2
        ones_t = sum(1 for i in range(n) if (first + i) % 2 == 1)
        if ones_t != ones:
            continue
        d = sum(1 for i, c in enumerate(s) if int(c) != (first + i) % 2)
        if best is None or d // 2 < best:
            best = d // 2
    return best
